package com.hmdp.ai.runtime.node;
import com.hmdp.ai.domain.agent.PublishedAgentDefinition;import com.hmdp.ai.domain.run.ExecutionContext;import com.hmdp.ai.domain.workflow.*;import java.util.*;
public final class NodeExecutionContext {private final ExecutionContext executionContext;private final PublishedAgentDefinition agent;private final WorkflowDefinition workflow;private final WorkflowNodeDefinition node;private final Map<String,Object>variables;private final List<WorkflowEdgeDefinition>outgoingEdges;public NodeExecutionContext(ExecutionContext e,PublishedAgentDefinition a,WorkflowDefinition w,WorkflowNodeDefinition n,Map<String,Object>v,List<WorkflowEdgeDefinition>edges){executionContext=e;agent=a;workflow=w;node=n;variables=v;outgoingEdges=Collections.unmodifiableList(new ArrayList<>(edges));}public ExecutionContext getExecutionContext(){return executionContext;}public PublishedAgentDefinition getAgent(){return agent;}public WorkflowDefinition getWorkflow(){return workflow;}public WorkflowNodeDefinition getNode(){return node;}public Map<String,Object>getVariables(){return variables;}public List<WorkflowEdgeDefinition>getOutgoingEdges(){return outgoingEdges;}}
